    static int readInt(DataInputStream dis) throws IOException {
        int num = 0;
        int c;
        while ((c = dis.read()) != -1 && (c < '0' || c > '9') && c != '-') ;
        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = dis.read();
