#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

int readInt() {
    int num = 0;
    int c;
    bool negative = false;
    while ((c = getchar()) != EOF && ((c < '0' || c > '9') && c != '-'));
    if (c == '-') {
        negative = true;
        c = getchar();
    }
    do {
        num = num * 10 + (c - '0');
    } while ((c = getchar()) >= '0' && c <= '9');
    return negative ? -num : num;
}

int countUniqueLetters(const std::string& s, int l, int r) {
    std::vector<bool> used(30, false);
    for (int i = l; i <= r; ++i) {
        used[s[i] - 'a'] = true;
    }
    return std::count(used.begin(), used.end(), true);
}

int computeDiff(int a, int b, int l, int r) {
    int first = (b < a) ? b : a - 1;
    int last = a - 1;
    std::string sb;
    for (int i = 0; i < a; ++i) {
        sb += ('a' + i);
    }
    char ch = (l < a) ? sb[last] : sb[first];
    for (int i = 0; i < b; ++i) {
        sb += ch;
    }
    std::vector<bool> usedLetters(30, false);
    for (int i = 0; i < a; ++i) {
        usedLetters[sb[sb.size() - i - 1] - 'a'] = true;
    }
    int ptr = 0;
    for (int i = 0; i < a; ++i) {
        while (usedLetters[ptr]) ++ptr;
        sb += ('a' + ptr);
        usedLetters[ptr] = true;
    }
    ch = sb[std::min(b, a - 1) + a + b];
    for (int i = 0; i < b; ++i) {
        sb += ch;
    }
    for (int i = 0; i < a + b; ++i) {
        sb += sb[i];
    }
    return countUniqueLetters(sb, l, r);
}

int main() {
    int a = readInt();
    int b = readInt();
    int l = readInt() - 1;
    int r = readInt() - 1;
    int totalLen = a + b;
    int diff = r - l;
    int answer;
    if (diff >= 2 * totalLen) {
        answer = std::max(a + 1, 2 * a - b);
    } else {
        r -= totalLen * (l / totalLen);
        l %= totalLen;
        answer = computeDiff(a, b, l, r);
    }
    std::cout << answer << "\n";
    return 0;
}

